#!/usr/bin/env python3
"""Validator for the Halcyon Threshold Commitment Ledger.

The ledger's only asset is being right. This script enforces the mechanical half
of that: schema conformance, evidence requirements, and review staleness. It
cannot check whether a quote is accurate -- that is the checker's job (see
CONTRIBUTING.md).

Usage:
    python verify.py ledger/commitments.csv
    python verify.py ledger/commitments.csv --due
    python verify.py ledger/commitments.csv --due --as-of 2027-03-01

Exit codes:
    0  clean (warnings may still be present)
    1  one or more errors -- do not commit
    2  could not read or parse the file
"""

import argparse
import csv
import datetime as dt
import re
import sys

FIELDS = [
    "id", "developer", "commitment_text", "source_url", "source_archive_url",
    "source_type", "date_made", "scope", "deadline", "specificity",
    "verifiability", "status", "status_evidence_url", "status_archive_url",
    "last_reviewed", "review_interval_days", "reviewer", "right_of_reply",
    "notes",
]

ALWAYS_REQUIRED = [
    "id", "developer", "commitment_text", "source_url", "source_archive_url",
    "source_type", "date_made", "scope", "deadline", "specificity",
    "verifiability", "status", "last_reviewed", "review_interval_days",
    "reviewer",
]

SOURCE_TYPES = {
    "policy_doc", "blog_post", "testimony", "regulatory_filing",
    "press_statement", "technical_report",
}
VERIFIABILITY = {"publicly_checkable", "third_party_auditable", "self_reported_only"}
STATUSES = {
    "active", "kept", "partially_kept", "missed", "withdrawn", "superseded",
    "unclear",
}
SPECIFICITY = {"1", "2", "3"}

ID_RE = re.compile(r"^HT-\d{4}$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
REPLY_RE = re.compile(r"^(sent|responded|declined):\d{4}-\d{2}-\d{2}$")

MAX_QUOTE = 300
EXAMPLE_ID = "HT-0000"

# Words that signal editorialising in a field that is supposed to be neutral.
LOADED = [
    "disappointingly", "predictably", "as expected", "yet again", "of course",
    "unsurprisingly", "egregious", "shameful", "blatant", "obviously",
]


def parse_date(value):
    if not DATE_RE.match(value or ""):
        return None
    try:
        return dt.date.fromisoformat(value)
    except ValueError:
        return None


def is_url(value):
    return isinstance(value, str) and value.startswith(("http://", "https://"))


class Report:
    def __init__(self):
        self.errors = []
        self.warnings = []

    def error(self, line, entry_id, message):
        self.errors.append((line, entry_id, message))

    def warn(self, line, entry_id, message):
        self.warnings.append((line, entry_id, message))


def check_row(row, line, report, seen_ids, today):
    entry_id = (row.get("id") or "").strip()

    if not ID_RE.match(entry_id):
        report.error(line, entry_id or "?", "id must look like HT-0001")
    if entry_id in seen_ids:
        report.error(line, entry_id, "duplicate id (ids are never reused)")
    seen_ids.add(entry_id)

    for field in ALWAYS_REQUIRED:
        if not (row.get(field) or "").strip():
            report.error(line, entry_id, "missing required field: %s" % field)

    # Enumerations.
    for field, allowed in (
        ("source_type", SOURCE_TYPES),
        ("verifiability", VERIFIABILITY),
        ("status", STATUSES),
        ("specificity", SPECIFICITY),
    ):
        value = (row.get(field) or "").strip()
        if value and value not in allowed:
            report.error(
                line, entry_id,
                "%s=%r is not one of: %s" % (field, value, ", ".join(sorted(allowed))),
            )

    # Quotes must be verbatim and short enough to be one commitment.
    quote = (row.get("commitment_text") or "").strip()
    if len(quote) > MAX_QUOTE:
